<h1>Healthcheck lead: <?php echo esc_html($data['contact']['company']); ?></h1><p><?php echo esc_html($data['contact']['first_name'].' '.$data['contact']['last_name'].' · '.$data['contact']['email'].' · '.$data['contact']['telephone']); ?></p><p>Sector: <?php echo esc_html($data['assessment']['sector']); ?> · Employee band: <?php echo esc_html($data['assessment']['employee_band']); ?> · Postcode: <?php echo esc_html($data['contact']['postcode']); ?></p><p>Audit requested: <?php echo $data['contact']['audit_requested'] ? 'Yes' : 'No'; ?></p><p>Internal opportunity tags: <?php echo esc_html(implode(', ',json_decode($data['assessment']['service_tags_json'],true)?:[])); ?></p><h2>Priority and review findings</h2><ul><?php foreach(array_merge($data['report']['priority'],$data['report']['review'])as$item):?><li><?php echo esc_html($item['recommendation']['heading']);?></li><?php endforeach;?></ul><p><a href="<?php echo esc_url($data['admin_url']); ?>">View assessment in WordPress</a></p>
